SELECT



ORDER BY


    ${filter.orderBy}


    ar_schedules.id DESC


LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM chart_accounts
WHERE is_active < 2 AND account_codes = #{accountCode}
 AND id != #{id}

mapper.update:
UPDATE ar_schedules SET
      is_active = 2,
      modified = NOW(),
      modified_by = #{userId}
WHERE id = #{id};

mapper.select:
SELECT CASE WHEN type = 1 THEN 'Trading' ELSE 'Software' END AS name, COUNT(sales_orders.customer_id) AS total, IFNULL(SUM(sales_orders.balance), 0) AS amount FROM sales_orders WHERE sales_orders.status > 0 AND sales_orders.balance > 0 AND sales_orders.id IN ( SELECT sales_order_id FROM ar_schedule_details INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND ar_schedules.branch_id = #{filter.branchId}
AND ar_schedules.start_date <= NOW() ) GROUP BY type

SELECT CASE WHEN type = 1 THEN 'Trading' ELSE 'Software' END AS name, COUNT(sales_orders.customer_id) AS total, IFNULL(SUM(sales_orders.balance), 0) AS amount FROM sales_orders WHERE sales_orders.status > 0 AND sales_orders.balance > 0 AND sales_orders.id IN ( SELECT sales_order_id FROM ar_schedule_details INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND ar_schedules.branch_id = #{filter.branchId}
) GROUP BY type

SELECT (SELECT CONCAT(last_name, ' ',first_name) FROM users WHERE id = ar_schedules.created_by) AS name, COUNT(sales_orders.customer_id) AS total, IFNULL(SUM(sales_orders.balance), 0) AS amount FROM sales_orders INNER JOIN ar_schedule_details ON sales_orders.id = ar_schedule_details.sales_order_id AND ar_schedule_details.is_active = 1 INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE sales_orders.status >= 1 AND sales_orders.balance > 0 AND ar_schedules.is_active = 1 AND sales_orders.id IN ( SELECT sales_order_id FROM ar_schedule_details INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND ar_schedules.branch_id = #{filter.branchId}
) GROUP BY ar_schedules.created_by

SELECT COUNT(DISTINCT sales_orders.customer_id) AS totalOrganization, IFNULL(SUM(sales_orders.balance), 0) AS amount FROM sales_orders WHERE sales_orders.status >= 1 AND sales_orders.balance > 0 AND sales_orders.id IN ( SELECT sales_order_id FROM ar_schedule_details INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id AND ar_schedule_details.is_active = 1 WHERE ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND ar_schedules.branch_id = #{filter.branchId}
)
AND branch_id = #{filter.branchId}

SELECT COUNT(sales_orders.customer_id) AS total, CONCAT('Week ', CEIL(DAY(ar_schedules.start_date) / 7)) AS name, SUM(sales_orders.balance) AS amount FROM sales_orders INNER JOIN ar_schedule_details ON sales_orders.id = ar_schedule_details.sales_order_id AND ar_schedule_details.is_active = 1 INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE sales_orders.status >= 1 AND sales_orders.balance > 0 AND ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND ar_schedules.branch_id = #{filter.branchId}
AND MONTH(ar_schedules.start_date) = MONTH(NOW()) AND YEAR(ar_schedules.start_date) = YEAR(NOW()) GROUP BY CEIL(DAY(ar_schedules.start_date) / 7) ORDER BY CEIL(DAY(ar_schedules.start_date) / 7);

SELECT IFNULL(SUM(sales_orders.balance), 0) AS totalAmountBookingOverdue FROM sales_orders INNER JOIN ar_schedule_details ON ar_schedule_details.sales_order_id = sales_orders.id INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE sales_orders.status > 0 AND sales_orders.balance > 0 AND sales_orders.id IN ( SELECT sales_order_id FROM ar_schedule_details INNER JOIN ar_schedules ON ar_schedules.id = ar_schedule_details.ar_schedule_id WHERE ar_schedules.is_close = 0 AND ar_schedules.is_active = 1
AND YEAR(ar_schedules.start_date) = YEAR(DATE(#{filter.dateFrom})) AND MONTH(ar_schedules.start_date) = MONTH(DATE(#{filter.dateFrom}))
AND ar_schedules.branch_id = #{filter.branchId}
) GROUP BY WEEK(ar_schedules.start_date, 1) ORDER BY WEEK(ar_schedules.start_date, 1);
